CREATE TABLE verification_runs (id text PRIMARY KEY, news_id text NOT NULL REFERENCES editorial_news(id), idempotency_key text NOT NULL UNIQUE, policy_id text NOT NULL, policy_version text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, actor_id text NOT NULL, error_code text);
CREATE TABLE verification_claims (id text PRIMARY KEY, news_id text NOT NULL REFERENCES editorial_news(id), claim_type text NOT NULL, claim_text text NOT NULL, importance text NOT NULL CHECK (importance IN ('PRIMARY','SECONDARY')), expected_subject text, expected_date timestamptz, created_at timestamptz NOT NULL);
CREATE TABLE verification_evidence (id text PRIMARY KEY, claim_id text NOT NULL REFERENCES verification_claims(id), source_id text NOT NULL, canonical_url text NOT NULL, authority text NOT NULL, evidence_type text NOT NULL, published_at timestamptz, event_date timestamptz, retrieved_at timestamptz NOT NULL, excerpt text CHECK (char_length(excerpt) <= 500), structured_facts jsonb NOT NULL, supports_claim boolean NOT NULL, contradicts_claim boolean NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE verification_results (id text PRIMARY KEY, run_id text NOT NULL UNIQUE REFERENCES verification_runs(id), news_id text NOT NULL REFERENCES editorial_news(id), status text NOT NULL, editorial_decision text NOT NULL, confidence integer NOT NULL CHECK (confidence BETWEEN 0 AND 100), result jsonb NOT NULL, evaluated_at timestamptz NOT NULL);
CREATE TABLE verification_claim_results (result_id text NOT NULL REFERENCES verification_results(id), claim_id text NOT NULL REFERENCES verification_claims(id), status text NOT NULL, confidence integer NOT NULL CHECK (confidence BETWEEN 0 AND 100), supporting_evidence_ids jsonb NOT NULL, contradicting_evidence_ids jsonb NOT NULL, reasons jsonb NOT NULL, PRIMARY KEY (result_id,claim_id));
CREATE INDEX verification_runs_news_id_idx ON verification_runs(news_id); CREATE INDEX verification_evidence_claim_id_idx ON verification_evidence(claim_id);
